import{_ as t,a,o as i,a4 as r}from"./chunks/framework.-FZumj2l.js";const c=JSON.parse('{"title":"Sitemaps","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/rest-api/admin/marketing/search-seo/sitemaps/index.md","filePath":"api/rest-api/admin/marketing/search-seo/sitemaps/index.md","lastUpdated":1784902076000}'),s={name:"api/rest-api/admin/marketing/search-seo/sitemaps/index.md"};function n(o,e,d,p,h,m){return i(),a("div",null,e[0]||(e[0]=[r('<h1 id="sitemaps" tabindex="-1">Sitemaps <a class="header-anchor" href="#sitemaps" aria-label="Permalink to &quot;Sitemaps&quot;">​</a></h1><p>A <strong>sitemap</strong> is an XML file that lists your storefront URLs for search-engine crawlers. Each definition records where the index file lives and, once built, which per-batch XML files it produced. It mirrors the admin <strong>Marketing → Search &amp; SEO → Sitemaps</strong> screen.</p><h2 id="how-a-sitemap-works" tabindex="-1">How a sitemap works <a class="header-anchor" href="#how-a-sitemap-works" aria-label="Permalink to &quot;How a sitemap works&quot;">​</a></h2><p>A sitemap has two stages: <strong>define</strong> it, then <strong>generate</strong> it.</p><ul><li><strong>Define</strong> — <code>file_name</code> is the index file&#39;s name (must end with <code>.xml</code>) and <code>path</code> is where that index file is written (must start and end with <code>/</code>, no <code>//</code>). Creating or updating a definition only stores these settings.</li><li><strong>Generate</strong> — building the actual XML is a separate, explicit step. The <a href="/api/rest-api/admin/marketing/search-seo/sitemaps-generate.html">generate</a> action walks every public category, product, and page, writes the index file plus the per-batch product / category / page XML files, and records their paths.</li></ul><p><strong>Built-file fields.</strong> <code>generatedAt</code> is the timestamp of the last generate run, <code>indexFile</code> is the path of the produced index file, and <code>generatedSitemaps</code> lists the per-batch XML files. All three stay empty until the first generate. They are returned on the <a href="/api/rest-api/admin/marketing/search-seo/sitemaps-detail.html">detail</a> endpoint — list rows carry only the flat definition fields.</p><p><strong>No auto-generation.</strong> Create and update never rebuild the XML — they only change the definition. Always call generate explicitly after a definition change.</p><p><strong>Disabled generation.</strong> If sitemap generation is turned off in the store configuration, the generate request still succeeds but produces no files.</p><p><strong>Deleting</strong> a sitemap removes both the definition row and its generated XML files.</p><h2 id="relation-to-other-menus" tabindex="-1">Relation to other menus <a class="header-anchor" href="#relation-to-other-menus" aria-label="Permalink to &quot;Relation to other menus&quot;">​</a></h2><p>A sitemap feeds search engines the URLs that the rest of <strong>Search &amp; SEO</strong> shapes — the canonical paths that <a href="/api/rest-api/admin/marketing/search-seo/url-rewrites/">URL Rewrites</a> redirect to and that drive organic discovery.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Endpoint</th></tr></thead><tbody><tr><td><a href="/api/rest-api/admin/marketing/search-seo/sitemaps-list.html">List</a></td><td><code>GET /api/admin/marketing/sitemaps</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/search-seo/sitemaps-detail.html">Detail</a></td><td><code>GET /api/admin/marketing/sitemaps/{id}</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/search-seo/sitemaps-create.html">Create</a></td><td><code>POST /api/admin/marketing/sitemaps</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/search-seo/sitemaps-update.html">Update</a></td><td><code>PUT /api/admin/marketing/sitemaps/{id}</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/search-seo/sitemaps-delete.html">Delete</a></td><td><code>DELETE /api/admin/marketing/sitemaps/{id}</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/search-seo/sitemaps-generate.html">Generate</a></td><td><code>POST /api/admin/marketing/sitemaps/{id}/generate</code></td></tr></tbody></table><p><code>indexFile</code> and <code>generatedSitemaps</code> are returned only on the <strong>detail</strong> endpoint — they are not present on list rows.</p><p>All Sitemaps endpoints require an admin Bearer token — see <a href="/api/rest-api/admin/authentication.html">Authentication</a>.</p>',15)]))}const g=t(s,[["render",n]]);export{c as __pageData,g as default};
